// Hand-written example variants for the demo's Copy studio, saved in the copy bank the way the studio
// saves them (one copy_variations row per field, rows of a variant sharing created_at). They are part of
// the fictional demo dataset: written by hand for the fictional Example Studio, never generated by AI,
// and labelled as samples in the console (model_used 'copy_studio:sample'). The demo runs with AI off,
// so the studio's generate button shows the AI-off state instead of a fake call.
import { addDays } from './demo-delivery'
import type { DemoCalendar } from './demo-account'

export const DEMO_COPY_SAMPLE_MODEL = 'copy_studio:sample'

export interface DemoCopySample {
  angle: string
  temperature: 'cold' | 'warm' | 'retargeting'
  goal: 'bookings'
  hook: string
  primary_text: string
  headline: string
  description: string
  cta: string
}

export const DEMO_COPY_SAMPLES: readonly DemoCopySample[] = [
  {
    angle: 'specific_benefit', temperature: 'cold', goal: 'bookings',
    hook: 'Shooting products this week?',
    primary_text: 'Shooting products this week? Bring them to a room with real window light. Set up, shoot and pack out without fighting your kitchen lamp.',
    headline: 'Window light, by the hour', description: 'Book a slot online', cta: 'BOOK_NOW',
  },
  {
    angle: 'objection_handling', temperature: 'warm', goal: 'bookings',
    hook: 'Not sure a studio is worth it for one shoot?',
    primary_text: 'Not sure a studio is worth it for one shoot? Book a short slot, bring two outfits and see how much faster the edit goes.',
    headline: 'Try one short slot first', description: 'Pick a time that suits you', cta: 'BOOK_NOW',
  },
  {
    angle: 'ugc', temperature: 'cold', goal: 'bookings',
    hook: 'POV: you stopped shooting against your bedroom wall.',
    primary_text: 'POV: you stopped shooting against your bedroom wall. Clean backdrop, soft light, room to move. The edit took half the time.',
    headline: 'Shoot somewhere with room', description: 'See the sets', cta: 'BOOK_NOW',
  },
  {
    angle: 'founder_story', temperature: 'retargeting', goal: 'bookings',
    hook: 'We opened this studio because we were tired of renting dark rooms.',
    primary_text: 'We opened this studio because we were tired of renting dark rooms. So we built the one we wanted: big windows, plain walls, nothing in the way.',
    headline: 'The studio we wanted to rent', description: 'See the space', cta: 'LEARN_MORE',
  },
]

const FIELDS = ['hook', 'primary_text', 'headline', 'description', 'cta'] as const

/** copy_variations rows for the demo account, one created_at per variant (days before the demo's anchor). */
export function demoCopyRows(calendar: DemoCalendar, accountId: string): Array<Record<string, string | number | boolean | null>> {
  return DEMO_COPY_SAMPLES.flatMap((sample, i) => FIELDS.map((field) => ({
    ad_account_id: accountId, copy_type: field, audience_type: 'unknown', angle: sample.angle, copy_text: sample[field],
    char_count: sample[field].length, is_approved: false, is_used: false, model_used: DEMO_COPY_SAMPLE_MODEL,
    performance_notes: `Sample example from the demo dataset, written by hand (not AI). Audience: ${sample.temperature}. Goal: ${sample.goal}.`,
    created_at: `${addDays(calendar.today, -(3 + i * 4))}T15:00:00Z`,
  })))
}
